(function(){
'use strict';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const agents=[
 {name:'Accounts Payable',role:'Finance',job:'Validate and prepare a supplier payment',tools:'Invoices · Purchase orders · Receiving · Vendor records',scenario:'Invoice INV-2041 from Northstar Supplies is due. Match it to the purchase order and delivery before proposing a $2,480 payment.',steps:['Read invoice INV-2041: Northstar Supplies, $2,480','Matched invoice lines to purchase order PO-883','Confirmed goods received against delivery GR-611','Checked duplicate invoices and verified the saved vendor payment details'],actions:['Pay $2,480 to Northstar Supplies for invoice INV-2041 using the existing verified vendor bank account']},
 {name:'Customer Support',role:'Customer operations',job:'Resolve a delayed customer order',tools:'Support · Orders · Carrier · Inventory',scenario:'Order #1048 is three days late. Alex Morgan qualifies for a $180 refund under the delivery policy.',steps:['Read Alex Morgan’s support conversation','Checked order #1048 and carrier: three days late','Verified refund eligibility against delivery policy','Prepared a $180 refund to the original payment method'],actions:['Refund $180 to the original payment method for Alex Morgan’s order #1048']},
 {name:'Sales Follow-up',role:'Revenue operations',job:'Recover an at-risk renewal',tools:'CRM · Contracts · Usage · Email',scenario:'Acme’s annual renewal is in 14 days. Usage fell 35%. Prepare a recovery offer within the contract limit.',steps:['Read Acme renewal record: 14 days remaining','Compared usage: down 35%','Checked contract: discount limited to 10%','Drafted a $9,000 annual renewal offer with onboarding support'],actions:['Email Acme’s recorded account owner the $9,000 annual renewal offer, including the 10% discount and onboarding support']},
 {name:'Release Monitor',role:'Engineering operations',job:'Investigate a failing release',tools:'GitHub · Error logs · Release history',scenario:'Checkout errors rose after release 2.8. Inspect logs and prepare a reviewed rollback.',steps:['Read checkout error logs for release 2.8','Compared release 2.8 with version 2.7','Identified payment timeout configuration change','Prepared the rollback plan to version 2.7'],actions:['Deploy rollback from version 2.8 to version 2.7 in the sample production environment']},
 {name:'Employee Onboarding',role:'People operations',job:'Prepare a new starter’s workspace',tools:'HR records · Role policy · Directory · IT catalog',scenario:'Jordan Lee joins as a support specialist. Prepare only the access allowed by the role policy.',steps:['Read Jordan Lee’s approved start date and role','Checked support specialist access policy','Confirmed manager and required training assignments','Prepared a support-only account access request'],actions:['Grant Jordan Lee the Support Specialist role in the sample help desk, with no billing or administrator access']}
].map(a=>({...a,version:1,instructions:'Follow the connected policy. Cite the source for each decision. Ask before sending, spending, deleting, deploying, or changing access.',examples:[],route:'Auto · local first',tested:false,active:false,events:[],decisions:[],running:false}));
let selected=0,tab='monitor';
const root=document.createElement('section');root.id='agentsView';root.hidden=true;root.className='agents-view';
document.querySelector('#integrationsView').before(root);
const nav=document.createElement('button');nav.className='nav';nav.dataset.view='agents';nav.innerHTML='<span aria-hidden="true">◎</span><span class="sidebar-label">Agents</span><small>Teach & monitor</small>';document.querySelector('.sidebar nav').append(nav);
const home=document.createElement('section');home.className='home-section agent-home agent-home-accountability';document.querySelector('#compute').before(home);
let homeSelected=0;
const homeDecisions=agents.map(()=> 'pending');
const receipts=agents.map(a=>a.steps.map((action,i)=>({agent:a.name,step:i+1,action,status:'completed_demo',route:'Local compute · illustrative',instruction_version:1})));
const hashes=agents.map(()=>[]);
async function hashRecord(record){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(record)));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
function renderHome(){
 const a=agents[homeSelected],decision=homeDecisions[homeSelected];
 home.innerHTML='<div class="agent-home-intro"><p class="home-kicker">MONITORED AGENTS</p><h2>Autonomous agents.<br>Accountable to you.</h2><p>Pick an agent. Inspect its four completed steps. You approve the action that comes next.</p></div><div class="agent-home-console"><aside class="agent-home-list" aria-label="Choose an agent"><p class="agent-label">AGENT NAME</p>'+agents.map((x,i)=>'<button data-home-agent="'+i+'" aria-pressed="'+(homeSelected===i)+'"><b>'+esc(x.name)+'</b><small>'+esc(x.role)+'</small><span>'+(homeDecisions[i]==='pending'?'4 steps complete · 1 approval':'Decision recorded')+'</span></button>').join('')+'<button class="text-button" data-view="agents">Teach & manage agents ↗</button></aside><section class="agent-home-ledger"><header><div><p class="agent-label">AGENT ACCOUNTABILITY</p><h3>'+esc(a.name)+'</h3></div><span class="agent-pill">'+(decision==='pending'?'Approval needed':'Decision recorded')+'</span></header><div class="agent-home-steps">'+a.steps.map((s,i)=>'<details'+(i===0?' open':'')+'><summary><span class="agent-step-number">0'+(i+1)+'</span><span><b>'+esc(s)+'</b><small>Autonomous · completed in this scenario</small></span><span class="agent-hash-link"># Receipt</span></summary><div class="agent-hash-detail"><p>SHA-256 fingerprint · sample action record</p><code>'+(hashes[homeSelected][i]||'Calculating…')+'</code><pre>'+esc(JSON.stringify(receipts[homeSelected][i],null,2))+'</pre><small>This hash checks this demo record’s contents. It is not a signed execution receipt.</small></div></details>').join('')+'</div><article class="agent-home-gate"><span class="agent-step-number">05</span><div><p class="agent-label">HUMAN APPROVAL</p><h4>'+esc(a.actions[0])+'</h4>'+(decision==='pending'?'<button class="primary" data-home-decision="approved">Approve demo action</button> <button class="secondary" data-home-decision="rejected">Reject</button>':'<p class="agent-decision-result">'+(decision==='approved'?'Approved by you · simulated action completed.':'Rejected by you · action did not run.')+'</p><button class="text-button" data-home-reset>Reset scenario</button>')+'</div></article><p class="agent-home-footnote">Interactive sample · no real payments, messages, deployments, or access changes.</p></section></div>';
}
home.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.homeAgent!==undefined){homeSelected=Number(b.dataset.homeAgent);selected=homeSelected;renderHome();render();}if(b.dataset.homeDecision&&homeDecisions[homeSelected]==='pending'){homeDecisions[homeSelected]=b.dataset.homeDecision;const a=agents[homeSelected];log(a,'Homepage demo: human '+b.dataset.homeDecision+' action — '+a.actions[0]);renderHome();render();}if(b.hasAttribute('data-home-reset')){homeDecisions[homeSelected]='pending';renderHome();}});
renderHome();
Promise.all(receipts.map((records,a)=>Promise.all(records.map(async(record,i)=>{try{hashes[a][i]=await hashRecord(record);}catch{hashes[a][i]='Hash unavailable in this browser';}})))).then(renderHome);

function log(a,text){a.events.push({time:new Date().toLocaleTimeString(),text,version:a.version,route:a.route});}
function render(){
 const a=agents[selected];
 root.innerHTML='<header class="agent-heading"><div><p class="eyebrow">MONITORED AGENTS</p><h1>Your agents. Your standards.</h1><p>Teach, test, and follow the work from request to approval.</p></div><span class="agent-pill">Interactive preview · session only</span></header><div class="agent-layout"><aside class="agent-roster" aria-label="Choose an agent">'+agents.map((x,i)=>'<button data-agent="'+i+'" aria-pressed="'+(selected===i)+'"><span class="agent-avatar">'+x.name[0]+'</span><span><b>'+x.name+'</b><small>'+x.role+'</small><em>'+(x.running?'Testing':x.decisions.includes('pending')?'Approval needed':x.active?'Active · demo':'Ready to test')+'</em></span></button>').join('')+'</aside><section class="agent-work"><header><div><h2>'+a.name+' <span>/ '+a.role+'</span></h2><p>'+a.job+'</p></div><span class="agent-pill">v'+a.version+'</span></header><nav class="agent-tabs" aria-label="Agent settings">'+['monitor','teach','models'].map(t=>'<button data-agent-tab="'+t+'" aria-pressed="'+(tab===t)+'">'+({monitor:'Monitor',teach:'Teach & improve',models:'Models & compute'}[t])+'</button>').join('')+'</nav><div class="agent-panel">'+(tab==='teach'?teach(a):tab==='models'?models(a):monitor(a))+'</div></section><aside class="agent-evidence"><h3>What '+a.name+' did</h3><p>Every step, route, and approval in one place.</p><div role="log" aria-live="polite">'+(a.events.length?a.events.map((e,i)=>'<details class="agent-event"><summary><small>'+esc(e.time)+'</small><b>'+esc(e.text)+'</b></summary><p>Event '+(i+1)+' · instructions v'+e.version+'<br>'+esc(e.route)+'<br>Simulated record · unsigned</p></details>').join(''):'<p class="agent-empty">Run a test scenario to see the activity record fill in.</p>')+'</div></aside></div>';
}
function monitor(a){return '<p class="agent-label">CONNECTED TOOLS · SAMPLE DATA</p><p>'+a.tools+'</p><div class="agent-scenario"><span class="agent-label">TEST SCENARIO</span><h3>'+a.job+'</h3><p>'+a.scenario+'</p><button class="primary" data-agent-test '+(a.running?'disabled':'')+'>'+(a.running?'Testing…':'Test this scenario')+'</button> <button class="secondary" data-agent-activate '+(!a.tested||a.running?'disabled':'')+'>'+(a.active?'Pause demo agent':'Activate demo agent')+'</button><small>Tests use a fixed sample plan. Activation changes this demo’s status; no background service runs.</small></div><div class="agent-guard"><b>Human approval required</b><p>Sending, payments, deletion, deployment, and access changes always pause for review.</p></div>'+ (a.decisions.length?'<h3>Review proposed actions</h3><p>Approve or reject each exact action individually. Nothing is approved automatically.</p>'+a.actions.map((action,i)=>'<article class="agent-approval"><p>'+esc(action)+'</p>'+(a.decisions[i]==='pending'?'<button class="secondary" data-agent-decision="approved" data-index="'+i+'">Approve demo action</button> <button class="secondary" data-agent-decision="rejected" data-index="'+i+'">Reject</button>':'<b>'+esc(a.decisions[i])+' · simulated</b>')+'</article>').join(''):'');}
function teach(a){return '<form id="agentTeachForm"><label>Instructions<textarea name="instructions" rows="5" required maxlength="6000">'+esc(a.instructions)+'</textarea></label><label>Add a teaching example<textarea name="example" rows="3" maxlength="3000" placeholder="Show a good result, a correction, or a rule to follow."></textarea></label><div class="agent-suggestions">'+['Here’s an example of a great result: ','Always check these sources first: ','Ask me before: ','When this happens, follow these steps: ','This result was wrong. Instead: '].map((s,i)=>'<button type="button" data-teach-suggestion="'+i+'">'+esc(s)+'</button>').join('')+'</div><button class="primary" type="submit">Save instructions as v'+(a.version+1)+'</button><p>Saved for this browser session. Instructions and examples guide the agent; this does not retrain a model.</p></form><h3>Teaching examples</h3>'+(a.examples.length?a.examples.map(e=>'<blockquote>'+esc(e)+'</blockquote>').join(''):'<p>No examples yet. Start with a result you would approve.</p>');}
function models(a){return '<form id="agentModelForm"><label>Preferred execution route<select name="route">'+['Auto · local first','Local only · Llama','Local only · Qwen','Specialist · Claude API','Specialist · OpenAI API'].map(r=>'<option '+(a.route===r?'selected':'')+'>'+r+'</option>').join('')+'</select></label><p>Auto prefers compatible local models for routine steps and proposes specialist help when needed. API access, hardware, and real routing must be connected in production.</p><div class="agent-model-note"><b>Your computer. Your compute.</b><p>Fully local steps have $0 hosted AI charges. Optional APIs, hardware, and electricity are separate.</p><a href="https://railcall.ai/downloads/chat/" target="_blank" rel="noopener noreferrer">Download the free suite ↗</a></div><button class="primary" type="submit">Save model preference</button><small>This selection is recorded in the test activity. The preview does not call or benchmark models.</small></form>';}
root.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.agent!==undefined){selected=Number(b.dataset.agent);render();return;}
 if(b.dataset.agentTab){tab=b.dataset.agentTab;render();return;}
 const a=agents[selected];
 if(b.hasAttribute('data-teach-suggestion')){const texts=['Here’s an example of a great result: ','Always check these sources first: ','Ask me before: ','When this happens, follow these steps: ','This result was wrong. Instead: '];const input=root.querySelector('[name="example"]');input.value=texts[Number(b.dataset.teachSuggestion)];input.focus();}
 if(b.hasAttribute('data-agent-test')&&!a.running){a.running=true;a.tested=false;a.decisions=[];log(a,'Started scenario test');render();let i=0;a.timer=setInterval(()=>{if(i<a.steps.length)log(a,a.steps[i++]);else{clearInterval(a.timer);a.running=false;a.tested=true;a.decisions=a.actions.map(()=> 'pending');log(a,'Paused: human approval required for each proposed action');}if(agents[selected]===a&&tab==='monitor')render();},550);}
 if(b.hasAttribute('data-agent-activate')&&a.tested&&!a.running){a.active=!a.active;log(a,a.active?'Demo agent activated; approval requirements retained':'Demo agent paused');render();}
 if(b.dataset.agentDecision&&a.decisions[Number(b.dataset.index)]==='pending'){const i=Number(b.dataset.index);a.decisions[i]=b.dataset.agentDecision;log(a,(b.dataset.agentDecision==='approved'?'Human approved; simulated execution: ':'Human rejected; action not executed: ')+a.actions[i]);render();}
});
root.addEventListener('submit',e=>{e.preventDefault();const a=agents[selected],data=new FormData(e.target);clearInterval(a.timer);a.running=false;
 if(e.target.id==='agentTeachForm'){const instructions=String(data.get('instructions')).trim();if(!instructions)return;a.instructions=instructions;const example=String(data.get('example')).trim();if(example)a.examples.push(example);a.version++;a.tested=false;a.active=false;a.decisions=[];log(a,'Saved teaching version '+a.version+'; test again before activation');}
 if(e.target.id==='agentModelForm'){a.route=String(data.get('route'));a.tested=false;a.active=false;a.decisions=[];log(a,'Updated model preference; test again before activation');}
 render();
});
render();
})();
